package domain

// ClaudeCodeDefaultModels optionally remaps Claude Code's haiku/sonnet/opus
// tiers to concrete upstream model names. When a tier is empty, the
// corresponding ANTHROPIC_DEFAULT_*_MODEL env var is omitted from the client
// configs generated by the "Use Key" modal and the "Import to CCS" deeplink,
// so upstreams that natively understand Claude model names (e.g. real
// Anthropic) need no configuration.
type ClaudeCodeDefaultModels struct {
	Haiku  string `json:"haiku,omitempty"`
	Sonnet string `json:"sonnet,omitempty"`
	Opus   string `json:"opus,omitempty"`
}
